1	//! Free-form measurement probe: a named, single-writer histogram
2	//! of sample durations in nanoseconds.
3	//!
4	//! The caller captures endpoints with any time source (typically
5	//! `minstant::Instant::now()`) and feeds the elapsed delta to
6	//! [`Probe::record`]. At report time [`Probe::report`] renders a
7	//! band-table summary under the enclosing bench's report, using
8	//! the same percentile boundaries so columns line up visually.
9	
10	use hdrhistogram::Histogram;
11	
12	use crate::harness::{fmt_commas, fmt_commas_f64};
13	
14	const BOUNDARY_PCTS: &[f64] = &[
15	    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
16	];
17	const BOUNDARY_NAMES: &[&str] = &[
18	    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
19	];
20	
21	/// Trimmed-stat range label from the populated bands below the
22	/// `p99-max` tail (`band_count`'s last band).
23	///
24	/// - Names the first..last populated non-tail band low-to-high like
25	///   the rows (`min-p99`, or `p10-p99` / `min-p90` when an end band
26	///   is empty), so the label tracks the real extent instead of a
27	///   fixed `min-p99` whose `min`/`p99` edges may not be present.
28	/// - Empty string when no non-tail band is populated (the caller
29	///   guards this with `trim_count > 0`, so the label goes unused).
30	fn trim_range_label(band_count: &[u64]) -> String {
31	    let trim_end = band_count.len() - 1; // exclude the p99-max tail band
32	    let first = (0..trim_end).find(|&i| band_count[i] > 0);
33	    let last = (0..trim_end).rev().find(|&i| band_count[i] > 0);
34	    match (first, last) {
35	        (Some(f), Some(l)) => format!("{}-{}", BOUNDARY_NAMES[f], BOUNDARY_NAMES[l + 1]),
36	        _ => String::new(),
37	    }
38	}
39	
40	/// Index of the band containing `mid_rank`, over [`BOUNDARY_PCTS`]
41	/// (`n_bands = BOUNDARY_PCTS.len() - 1`).
42	///
43	/// Right-closed `(lower, upper]` — a rank exactly on a boundary falls
44	/// in the band that boundary caps, mirroring
45	/// [`crate::harness::print_report`]'s convention. `mid_rank` is the
46	/// Hazen plotting position `(i - 0.5) / n`.
47	fn band_index(mid_rank: f64) -> usize {
48	    let n_bands = BOUNDARY_PCTS.len() - 1;
49	    BOUNDARY_PCTS[1..]
50	        .iter()
51	        .position(|&b| mid_rank <= b)
52	        .unwrap_or(n_bands - 1)
53	}
54	
55	/// A named, single-writer nanosecond histogram. Not `Sync`;
56	/// cross-thread *sharing* is out of scope. `Send` so probes can
57	/// be moved between threads (e.g. returned via a
58	/// `JoinHandle<Probe>` on shutdown).
59	pub struct Probe {
60	    name: String,
61	    hist: Histogram<u64>,
62	}
63	
64	impl Probe {
65	    /// Create an empty probe. Histogram bounds (1 ns — 60 s,
66	    /// 3 significant figures) mirror the harness.
67	    ///
68	    /// Exits the process (code 1) if the hardware tick counter
69	    /// isn't usable — see [`crate::ticks::require_ok`].
70	    pub fn new(name: &str) -> Self {
71	        crate::ticks::require_ok();
72	        Self {
73	            name: name.to_string(),
74	            hist: Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
75	        }
76	    }
77	
78	    /// Record a single sample. Values of 0 are clamped to 1 since
79	    /// the histogram's lower bound is 1 ns; sub-ns deltas from
80	    /// coarse timers round up rather than panic.
81	    pub fn record(&mut self, ns: u64) {
82	        self.hist.record(ns.max(1)).unwrap();
83	    }
84	
85	    /// Render a band-table report for this probe, indented one
86	    /// level deeper than the enclosing bench's report. Values are
87	    /// raw, as in the harness report, and bands are right-closed
88	    /// `(lower, upper]` (see [`band_index`]) to match it.
89	    /// `decimals` (`--decimals`) applies to the computed mean and
90	    /// stdev columns; `first`/`last`/`range` are recorded integer
91	    /// ns, so they stay integer — more digits would be artifacts.
92	    pub fn report(&self, decimals: usize) {
93	        let sample_count = self.hist.len();
94	        println!(
95	            "  probe: {} [count={}]",
96	            self.name,
97	            fmt_commas(sample_count)
98	        );
99	        if sample_count == 0 {
100	            println!();
101	            return;
102	        }
103	
104	        let n_bands = BOUNDARY_PCTS.len() - 1;
105	        let mut band_first = vec![u64::MAX; n_bands];
106	        let mut band_last = vec![0u64; n_bands];
107	        let mut band_count = vec![0u64; n_bands];
108	        let mut band_sum = vec![0u128; n_bands];
109	
110	        let mut cumulative = 0u64;
111	        for iv in self.hist.iter_recorded() {
112	            let value = iv.value_iterated_to();
113	            let count = iv.count_at_value();
114	            let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
115	            let idx = band_index(mid_rank);
116	            band_first[idx] = band_first[idx].min(value);
117	            band_last[idx] = band_last[idx].max(value);
118	            band_count[idx] += count;
119	            band_sum[idx] += value as u128 * count as u128;
120	            cumulative += count;
121	        }
122	
123	        struct BandRow {
124	            label: String,
125	            first: String,
126	            last: String,
127	            range: String,
128	            count: String,
129	            mean: String,
130	        }
131	
132	        let mut rows: Vec<BandRow> = Vec::new();
133	        for i in 0..n_bands {
134	            if band_count[i] == 0 {
135	                continue;
136	            }
137	            let mean_val = band_sum[i] as f64 / band_count[i] as f64;
138	            rows.push(BandRow {
139	                label: format!("{}-{}", BOUNDARY_NAMES[i], BOUNDARY_NAMES[i + 1]),
140	                first: fmt_commas(band_first[i]),
141	                last: fmt_commas(band_last[i]),
142	                range: fmt_commas(band_last[i] - band_first[i] + 1),
143	                count: fmt_commas(band_count[i]),
144	                mean: fmt_commas_f64(mean_val, decimals),
145	            });
146	        }
147	
148	        // Trimmed-stat range label, derived from the populated bands
149	        // (empty when none — then `trim_count > 0` skips the rows).
150	        let trim_range = trim_range_label(&band_count);
151	        let mean_trim_label = format!("mean {trim_range}");
152	        let stdev_trim_label = format!("stdev {trim_range}");
153	
154	        let label_w = rows
155	            .iter()
156	            .map(|r| r.label.len())
157	            .max()
158	            .unwrap_or(0)
159	            .max(stdev_trim_label.len());
160	        let first_w = rows.iter().map(|r| r.first.len()).max().unwrap_or(0);
161	        let last_w = rows.iter().map(|r| r.last.len()).max().unwrap_or(0);
162	        let range_w = rows.iter().map(|r| r.range.len()).max().unwrap_or(0);
163	        let count_w = rows.iter().map(|r| r.count.len()).max().unwrap_or(0);
164	        let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0);
165	
166	        const INDENT: &str = "    ";
167	        const GAP: &str = "    ";
168	
169	        let first_col = INDENT.len() + label_w + 1 + first_w;
170	        let last_gap = " ns".len() + GAP.len() + last_w;
171	        let range_gap = " ns".len() + GAP.len() + range_w;
172	        let count_gap = " ns".len() + GAP.len() + count_w;
173	        let mean_gap = GAP.len() + mean_w;
174	        println!(
175	            "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
176	            "first", "last", "range", "count", "mean",
177	        );
178	
179	        for r in &rows {
180	            println!(
181	                "{INDENT}{:<label_w$} {:>first_w$} ns{GAP}{:>last_w$} ns{GAP}{:>range_w$} ns{GAP}{:>count_w$}{GAP}{:>mean_w$} ns",
182	                r.label, r.first, r.last, r.range, r.count, r.mean,
183	            );
184	        }
185	
186	        let hist_mean = self.hist.mean();
187	        let skip = first_w
188	            + " ns".len()
189	            + GAP.len()
190	            + last_w
191	            + " ns".len()
192	            + GAP.len()
193	            + range_w
194	            + " ns".len()
195	            + GAP.len()
196	            + count_w;
197	        println!(
198	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
199	            "mean",
200	            "",
201	            fmt_commas_f64(hist_mean, decimals),
202	        );
203	        println!(
204	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
205	            "stdev",
206	            "",
207	            fmt_commas_f64(self.hist.stdev(), decimals),
208	        );
209	
210	        let trim_count: u64 = band_count[..n_bands - 1].iter().sum();
211	        if trim_count > 0 {
212	            let trim_sum: u128 = band_sum[..n_bands - 1].iter().sum();
213	            let trim_mean = trim_sum as f64 / trim_count as f64;
214	
215	            let mut trim_var_sum = 0.0f64;
216	            let mut trim_var_count = 0u64;
217	            let mut cum = 0u64;
218	            for iv in self.hist.iter_recorded() {
219	                let value = iv.value_iterated_to();
220	                let count = iv.count_at_value();
221	                let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
222	                let idx = band_index(mid_rank);
223	                if idx < n_bands - 1 {
224	                    let diff = value as f64 - trim_mean;
225	                    trim_var_sum += diff * diff * count as f64;
226	                    trim_var_count += count;
227	                }
228	                cum += count;
229	            }
230	            let trim_stdev = if trim_var_count > 1 {
231	                (trim_var_sum / trim_var_count as f64).sqrt()
232	            } else {
233	                0.0
234	            };
235	
236	            println!(
237	                "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
238	                mean_trim_label,
239	                "",
240	                fmt_commas_f64(trim_mean, decimals),
241	            );
242	            println!(
243	                "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
244	                stdev_trim_label,
245	                "",
246	                fmt_commas_f64(trim_stdev, decimals),
247	            );
248	        }
249	        println!();
250	    }
251	}
252	
253	#[cfg(test)]
254	mod tests {
255	    use super::*;
256	
257	    /// A `band_count` vec (len = n_bands) with the given band
258	    /// indices marked populated.
259	    fn counts(populated: &[usize]) -> Vec<u64> {
260	        let mut c = vec![0u64; BOUNDARY_PCTS.len() - 1];
261	        for &i in populated {
262	            c[i] = 1;
263	        }
264	        c
265	    }
266	
267	    #[test]
268	    fn trim_range_label_spans_populated_bands() {
269	        // Full: min-p1 band (0) through p90-p99 band (10) -> min-p99.
270	        assert_eq!(trim_range_label(&counts(&[0, 5, 10])), "min-p99");
271	        // The p99-max tail band (11) is excluded even when populated.
272	        assert_eq!(trim_range_label(&counts(&[2, 10, 11])), "p10-p99");
273	        // Empty p90-p99 band: upper end is the last populated band.
274	        assert_eq!(trim_range_label(&counts(&[0, 9])), "min-p90");
275	        // One populated band is just that band's own low-high label.
276	        assert_eq!(trim_range_label(&counts(&[6])), "p50-p60");
277	        // No populated non-tail band yields an empty label (unused).
278	        assert_eq!(trim_range_label(&counts(&[])), "");
279	    }
280	
281	    #[test]
282	    fn band_index_right_closed_on_boundary() {
283	        // Band label for a rank (probe rows are low-high ranges).
284	        let label = |r: f64| {
285	            let i = band_index(r);
286	            format!("{}-{}", BOUNDARY_NAMES[i], BOUNDARY_NAMES[i + 1])
287	        };
288	
289	        // Right-closed: a rank exactly on a boundary lands in the band
290	        // that boundary caps (upper edge), not the next one up.
291	        assert_eq!(label(0.5), "p40-p50"); // single-sample mid-rank
292	        assert_eq!(label(0.4), "p30-p40"); // exactly the p40 boundary
293	        assert_eq!(label(0.99), "p90-p99"); // exactly p99 → last non-tail band
294	
295	        // Strictly-interior ranks are unaffected by the closed end.
296	        assert_eq!(label(0.55), "p50-p60");
297	        assert_eq!(label(0.05), "p1-p10");
298	    }
299	}
