227	/// Block-replication statistics from a sleep-separated run —
228	/// each block is a mini-run (own sleep re-roll + warm-up), so the
229	/// spread of block means yields an honest-per-invocation CI and
230	/// LSC. See
231	/// notes/design.md#within-invocation-replication-sleep-separated-blocks.
232	#[derive(Debug)]
233	pub struct BlockStats {
234	    /// Number of blocks (Y).
235	    pub blocks: u64,
236	    /// Mean of the per-block means, ns.
237	    pub mean_ns: f64,
238	    /// 95% confidence half-width on `mean_ns`:
239	    /// `t(0.975, Y-1) * s / sqrt(Y)`, ns.
240	    pub ci95_ns: f64,
241	    /// Least significant change vs an equal-Y run of another
242	    /// implementation: `t(0.975, 2Y-2) * s * sqrt(2/Y)`, ns.
243	    pub lsc_ns: f64,
244	}
245	
246	impl BlockStats {
247	    /// Fit from per-block means (ns). Caller guarantees
248	    /// `means.len() >= 2` (the CLI enforces `--blocks 2..`).
249	    fn from_means(means: &[f64]) -> BlockStats {
250	        let y = means.len() as f64;
251	        let mean = means.iter().sum::<f64>() / y;
252	        let var = means.iter().map(|m| (m - mean) * (m - mean)).sum::<f64>() / (y - 1.0);
253	        let s = var.sqrt();
254	        let yy = means.len() as u64;
255	        BlockStats {
256	            blocks: yy,
257	            mean_ns: mean,
258	            ci95_ns: t975(yy - 1) * s / y.sqrt(),
259	            lsc_ns: t975(2 * yy - 2) * s * (2.0 / y).sqrt(),
260	        }
261	    }
262	}
263	
264	/// Two-sided 95% Student-t quantile (`t(0.975, df)`), table for
265	/// df ≤ 30, then the conservative 2.0 (the true value falls from
266	/// 2.042 toward the normal 1.96).
267	fn t975(df: u64) -> f64 {
268	    const TABLE: [f64; 30] = [
269	        12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160,
270	        2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056,
271	        2.052, 2.048, 2.045, 2.042,
272	    ];
273	    match df {
274	        0 => f64::INFINITY,
275	        1..=30 => TABLE[(df - 1) as usize],
276	        _ => 2.0,
277	    }
278	}
279	
280	/// Everything a finished [`run_adaptive`] run produced — the
281	/// histogram plus the metadata [`print_report`] needs and the
282	/// time-ordered [`BatchSummary`] series the gauge reads.
283	#[derive(Debug)]
284	pub struct RunOutput {
285	    /// Per-call values (ps) of every sample.
286	    pub hist: Histogram<u64>,
287	    /// Samples taken (outer-loop count).
288	    pub outer: u64,
289	    /// Calls per sample (inner-loop count).
290	    pub inner: u64,
291	    /// Measured wall time, seconds.
292	    pub duration_s: f64,
293	    /// Seconds the system spent suspended during the run (see
294	    /// [`ClockPair`]); [`print_report`] flags poisoned stats
295	    /// when non-trivial.
296	    pub suspended_s: f64,
297	    /// Block-replication stats — `Some` only for `--blocks`
298	    /// runs.
299	    pub block_stats: Option<BlockStats>,
300	    /// Time-ordered per-batch summaries from the pipeline.
301	    pub batches: Vec<BatchSummary>,
302	    /// Time-ordered micro-probe summaries — the environment
303	    /// grade's input. One series, two stretches: see
304	    /// [`RunOutput::warmup_probes`].
305	    pub probes: Vec<ProbeSummary>,
306	    /// How many leading [`RunOutput::probes`] came from warmup.
307	    /// Splits the series into the stretch measured before the
308	    /// bench ran and the stretch measured alongside it — graded
309	    /// separately, because a ramp warmup absorbed is not a fault
310	    /// and blending the two invents a step at the boundary.
311	    pub warmup_probes: usize,
312	}
313	
314	/// Drive `bench` against `cfg` and return a [`RunOutput`].
315	///
316	/// After a fixed warmup, `inner` is auto-sized so apparatus framing
317	/// doesn't dominate (skipped when `cfg.inner_override` is set). The
318	/// outer loop runs either for `cfg.outer_override` iterations or
319	/// until `cfg.target_seconds` elapses — as one continuous run, or
320	/// split into `cfg.blocks` sleep-separated blocks (`block_stats`
321	/// is `Some` only then). Samples flow through the
322	/// [`BatchPipeline`], so the output carries the run's time axis
323	/// as per-batch summaries alongside the histogram.
324	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> RunOutput {
325	    let (origin, warm_probes, prober) = warmup_and_probe(bench);
326	
327	    let step_cost_ns = estimate_step_cost(bench);
328	    // The last warmup probe is the most-warmed one, so sizing
329	    // reads a post-warmup frame by construction.
330	    let frame_ns = match warm_probes.last() {
331	        Some(p) => (p.floor_q_ps as f64 / PS_PER_NS).max(1.0),
332	        None => 1.0,
333	    };
334	    let inner = cfg
335	        .inner_override
336	        .unwrap_or_else(|| pick_inner(step_cost_ns, frame_ns));
337	
338	    let warmup_probes = warm_probes.len();
339	    let mut pipeline = BatchPipeline::new(origin, prober, warm_probes, cfg.seam_probes);
340	    let clocks = ClockPair::now();
341	    let (block_stats, duration_s) = match cfg.blocks {
342	        Some(blocks) => {
343	            let (duration_s, stats) = run_blocked(
344	                bench,
345	                &mut pipeline,
346	                blocks,
347	                cfg.outer_override,
348	                cfg.target_seconds,
349	                inner,
350	            );
351	            (Some(stats), duration_s)
352	        }
353	        None => match cfg.outer_override {
354	            Some(outer) => (None, run_counted(bench, &mut pipeline, outer, inner)),
355	            None => (
356	                None,
357	                run_timed(bench, &mut pipeline, cfg.target_seconds, inner),
358	            ),
359	        },
360	    };
361	    let (hist, batches, probes) = pipeline.finish();
362	    let outer = match cfg.outer_override {
363	        Some(outer) if cfg.blocks.is_none() => outer,
364	        _ => hist.len(),
365	    };
366	    RunOutput {
367	        hist,
368	        outer,
369	        inner,
370	        duration_s,
371	        suspended_s: clocks.suspended_s(),
372	        block_stats,
373	        batches,
374	        probes,
375	        warmup_probes,
376	    }
377	}
378	
379	/// Run `blocks` sleep-separated blocks: each block sleeps a
380	/// random [`BLOCK_SLEEP_MS_MIN`]..=[`BLOCK_SLEEP_MS_MAX`] ms
381	/// (re-rolls scheduler / frequency / mode-mix state), steps
382	/// unrecorded for [`BLOCK_WARMUP_SECONDS`] (post-wake ramp), then
383	/// measures its share of the budget (`outer / blocks` samples, or
384	/// `target_seconds / blocks`). All samples land in one histogram;
385	/// per-block means feed [`BlockStats`]. The returned duration is
386	/// wall time including sleeps and warm-ups.
387	fn run_blocked<B: Bench>(
388	    bench: &mut B,
389	    pipeline: &mut BatchPipeline,
390	    blocks: u64,
391	    outer_override: Option<u64>,
392	    target_seconds: f64,
393	    inner: u64,
394	) -> (f64, BlockStats) {
395	    let mut dither = Dither::new();
396	    let mut means: Vec<f64> = Vec::with_capacity(blocks as usize);
397	    let run_start = std::time::Instant::now();
398	    for b in 0..blocks {
399	        let ms =
400	            BLOCK_SLEEP_MS_MIN + dither.rand_u64() % (BLOCK_SLEEP_MS_MAX - BLOCK_SLEEP_MS_MIN + 1);
401	        std::thread::sleep(std::time::Duration::from_millis(ms));
402	
403	        let warm_start = std::time::Instant::now();
404	        while warm_start.elapsed().as_secs_f64() < BLOCK_WARMUP_SECONDS {
405	            black_box(bench.step());
406	        }
407	        // Align batch boundaries to blocks: the flush moves the
408	        // batch clock past the sleep + warmup gap, so no batch
409	        // spans time the bench wasn't running.
410	        pipeline.flush();
411	
412	        let mut sum_ps: u128 = 0;
413	        let mut n: u64 = 0;
414	        match outer_override {
415	            Some(outer) => {
416	                // Distribute the remainder over the first blocks.
417	                let count = outer / blocks + u64::from(b < outer % blocks);
418	                for _ in 0..count {
419	                    sum_ps += u128::from(record_sample(bench, inner, pipeline, &mut dither));
420	                    n += 1;
421	                }
422	            }
423	            None => {
424	                let budget = target_seconds / blocks as f64;
425	                let block_start = std::time::Instant::now();
426	                loop {
427	                    sum_ps += u128::from(record_sample(bench, inner, pipeline, &mut dither));
428	                    n += 1;
429	                    if block_start.elapsed().as_secs_f64() >= budget {
430	                        break;
431	                    }
432	                }
433	            }
434	        }
435	        pipeline.flush();
436	        if n > 0 {
437	            means.push(sum_ps as f64 / n as f64 / PS_PER_NS);
438	        }
439	    }
440	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
441	    let stats = BlockStats::from_means(&means);
442	    (duration_s, stats)
443	}
444	
445	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
446	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
447	        .map(|_| {
448	            let start = std::time::Instant::now();
449	            for _ in 0..ESTIMATE_STEPS {
450	                black_box(bench.step());
451	            }
452	            let total = start.elapsed().as_nanos() as u64;
