542	    ///   hand.
543	    fn probe(&mut self, since: std::time::Instant) -> ProbeSummary {
544	        let t_start_s = since.elapsed().as_nanos() as f64 / 1e9;
545	        self.groups.clear();
546	        self.pairs.clear();
547	        for _ in 0..PROBE_GROUPS {
548	            let group_start = std::time::Instant::now();
549	            for _ in 0..PROBE_GROUP_PAIRS {
550	                let start = std::time::Instant::now();
551	                self.pairs.push(start.elapsed().as_nanos() as u32);
552	            }
553	            let total_ns = group_start.elapsed().as_nanos() as f64;
554	            self.groups
