556	        }
557	        self.groups.sort_unstable();
558	
559	        let floor_q_ps = quantile_at(&self.groups, ENV_FLOOR_Q).max(1);
560	        let spread_q_ps = quantile_at(&self.groups, ENV_SPREAD_Q);
561	        let sum: u128 = self.groups.iter().map(|&g| u128::from(g)).sum();
562	        let mean_ps = sum as f64 / self.groups.len() as f64;
563	
564	        let cut_ps = over_floor_cut(floor_q_ps, ENV_OVER_ADD_PS);
565	        let cut_ns = cut_ps as f64 / PS_PER_NS;
566	        let over_pairs = self
567	            .pairs
568	            .iter()
