570	            .count() as u64;
571	
572	        ProbeSummary {
573	            t_start_s,
574	            groups: self.groups.len() as u64,
575	            floor_q_ps,
576	            spread_q_ps,
577	            mean_ps,
578	            pairs: self.pairs.len() as u64,
