/// - A probe qualifies only if its own floor is in the band **and**
///   the median of every floor from it onward is too. The suffix
///   median is what makes this robust: one late outlier can't
///   push settle time to the end of the stretch, and one early
///   probe that happens to land at the settled value can't claim
///   the box settled before it did.
/// - A stretch that never settles reports its last probe's time —
///   "not settled by the end", with no special-case value to
///   interpret.
pub fn settle_s(warm: &[ProbeSummary], tail: &[ProbeSummary]) -> Option<f64> {
    let floors: Vec<f64> = warm.iter().map(|p| p.floor_q_ps as f64).collect();
    let tail_floors: Vec<f64> = tail.iter().map(|p| p.floor_q_ps as f64).collect();
    let level = median(&tail_floors)?;
    if level <= 0.0 {
        return None;
    }
    for (i, p) in warm.iter().enumerate() {
        let own = (floors[i] - level).abs() / level;
        if own <= SETTLE_TOL && split_change(&tail_floors, &floors[i..]) <= SETTLE_TOL {
            return Some(p.t_start_s);
        }
    }
    warm.last().map(|p| p.t_start_s)
}

input.new_string:
/// - The rule is "when did the floor last leave the band": the
///   settle time is the probe after the last one outside it, so
///   movement anywhere in the stretch is reflected, not just
///   movement a suffix median survives. A suffix-median rule was
///   tried first and read `settled 0.00s` on stretches whose own
///   `drift` signal graded F — a minority of moved probes never
///   shifts the median.
/// - Floors are smoothed by a 3-probe median first, so a single
///   preempted probe can't claim the box was unsettled until the
///   end of warmup. [`SMOOTH_HALF`] sets the window.
/// - A stretch that never settles reports its last probe's time —
///   "not settled by the end", with no special-case value to
///   interpret.
pub fn settle_s(warm: &[ProbeSummary], tail: &[ProbeSummary]) -> Option<f64> {
    let tail_floors: Vec<f64> = tail.iter().map(|p| p.floor_q_ps as f64).collect();
    let level = median(&tail_floors)?;
    if level <= 0.0 {
        return None;
    }
    let smoothed = smooth_floors(warm);
    let last_out = smoothed
        .iter()
        .rposition(|&f| (f - level).abs() / level > SETTLE_TOL);
    match last_out {
        // The probe after the last excursion — or the final
        // probe's own time when that excursion was the final one.
        Some(i) => warm.get(i + 1).or_else(|| warm.last()),
        None => warm.first(),
    }
    .map(|p| p.t_start_s)
}

/// Probes each side of a floor in [`smooth_floors`]'s median
/// window — 1, so the window is three probes.
const SMOOTH_HALF: usize = 1;

/// Probe floors smoothed by a [`SMOOTH_HALF`]-radius running
/// median, so an isolated disturbed probe reads as its
/// neighbours. Windows clamp at the ends rather than shrinking
/// the series.
fn smooth_floors(probes: &[ProbeSummary]) -> Vec<f64> {
    let floors: Vec<f64> = probes.iter().map(|p| p.floor_q_ps as f64).collect();
    (0..floors.len())
        .map(|i| {
            let lo = i.saturating_sub(SMOOTH_HALF);
            let hi = (i + SMOOTH_HALF + 1).min(floors.len());
            median(&floors[lo..hi]).unwrap_or(floors[i]) // OK: window is non-empty
        })
        .collect()
}

