    match run_once(cfg) {
        Ok(r) => {
            let (w, d) = r.letters();
            let settle = match r.settle {
                Some(Settle::At(s)) => format!("{s:.2}s"),
                Some(Settle::Never) => "not".to_string(),
                None => "-".to_string(),
            };
            println!(
                "  {:<5} {w:<7} {d:<8} {:<7} {settle:<8} {}",
