                r.worst,
                r.mean
            );
            runs.push(r);
        }
        Err(e) => {
            eprintln!("error: qualify run {}: {e}", i + 1);
            return 2;
        }
    }
}

let mut scores: Vec<i64> = runs.iter().map(|r| score(r.worst)).collect();
